import itertools
p=13
fixed={4:3,9:1}
# brute force with pruning using Costas property

def is_costas(perm):
    n=len(perm)
    seen=set()
    for i in range(n):
        for j in range(i+1,n):
            dr=perm[j]-perm[i]
            dc=j-i
            if (dr,dc) in seen:
                return False
            seen.add((dr,dc))
    return True

cols=list(range(p))
# generate permutations respecting fixed
remaining_cols=[c for c in cols if c not in fixed]
remaining_vals=[v for v in range(p) if v not in fixed.values()]
for perm_vals in itertools.permutations(remaining_vals):
    perm=[None]*p
    for c,v in fixed.items():
        perm[c]=v
    for c,v in zip(remaining_cols, perm_vals):
        perm[c]=v
    if is_costas(perm):
        print('found',perm)
        break
else:
    print('none')
